extra_css:
/* theme: neon-live (2026-10-27) */
:root,:root:not(x){--bg:#130c25;--fg:#f1ecff;--muted:#b9b0d6;--line:#3a2d63;--card:#1d1436;--soft:#271c47;--accent:#ff4fc4;--accent2:#9f7bff}
@media (prefers-color-scheme:dark){:root{--bg:#130c25;--fg:#f1ecff;--muted:#b9b0d6;--line:#3a2d63;--card:#1d1436;--soft:#271c47;--accent:#ff4fc4;--accent2:#9f7bff}}
body{background:radial-gradient(1200px 500px at 50% -200px,#3b1a6e 0,transparent 70%),var(--bg);font-family:"M PLUS Rounded 1c","Hiragino Maru Gothic ProN","Hiragino Sans",sans-serif}
header{background:rgba(19,12,37,.92);border-bottom:1px solid #ff4fc455;box-shadow:0 1px 18px #ff4fc433}
.logo,.hero h1,article h1,.sec-h,article h2{font-weight:800}
.logo{color:#fff;text-shadow:0 0 10px #9f7bff}.logo span{color:#ff4fc4;text-shadow:0 0 12px #ff4fc4}
.gnav a{background:transparent;border:1.5px solid #9f7bff88;color:#e6dcff}
.gnav a:hover,.gnav a.on{background:#ff4fc4;border-color:#ff4fc4;color:#1a0b2e;box-shadow:0 0 14px #ff4fc4aa}
.hero-img{border:1px solid #ff4fc466;box-shadow:0 0 28px #9f7bff55}
.hero h1{text-shadow:0 0 16px #9f7bff99}
.sec-h{border-bottom:2px solid #ff4fc4;box-shadow:0 6px 10px -8px #ff4fc4}
.card{border:1px solid var(--line);border-radius:14px}
.card:hover{border-color:#ff4fc4;box-shadow:0 0 18px #ff4fc455}
.tag{background:linear-gradient(90deg,#ff4fc4,#9f7bff);color:#1a0b2e;font-weight:800}
article h2{background:linear-gradient(90deg,#2b1652,#1d1436);border-left:0;border-radius:10px;box-shadow:inset 0 0 0 1.5px #ff4fc4,0 0 14px #ff4fc444;padding:10px 16px}
article h3{border-bottom:2px dashed #9f7bff}
.toc{border-top-color:#9f7bff}
.picks{border:2px dashed #ff4fc4;border-radius:16px;position:relative}
.picks-h::before{content:"🎫 "}
.next{border-color:#9f7bff;background:#1d1436}
.avatar{background:linear-gradient(135deg,#ff4fc4,#9f7bff)}
aside .box-h{border-bottom-color:#ff4fc4}
.mini b{background:#9f7bff}
th{background:#271c47}
footer{background:#0e0820;border-top:1px solid #ff4fc444}

/* hero-base: 2026-10-27 トップの見せ場の共通部分 */
.hx{padding:24px 0 6px}.hx-eyebrow{font-size:13px;font-weight:700;letter-spacing:.08em;color:var(--accent);margin:0 0 8px}
.hx-h1{font-size:clamp(28px,5vw,46px);line-height:1.3;margin:0 0 14px}.hx-h1 em{font-style:normal;color:var(--accent)}
.hx-lead{color:var(--muted);font-size:15px;margin:0 0 22px;max-width:680px}
.hx-chips{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 26px}.hx-chips a{text-decoration:none;font-size:13px;padding:5px 12px}
.hx-vs{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;margin:0 0 22px}.hx-vs p{margin:0;font-size:13px;color:var(--muted)}
.hx-k{font-size:12px;color:var(--muted)}.hx-v{font-size:clamp(20px,3.4vw,28px);font-weight:800;line-height:1.35;margin:4px 0}
.hx-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 22px}.hx-stats b{display:block;line-height:1.1;font-variant-numeric:tabular-nums}.hx-stats span{font-size:12px;color:var(--muted)}
.hx-steps{list-style:none;padding:0;margin:0 0 8px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.hx-steps strong{display:block;font-size:15px}.hx-steps span{font-size:12px;color:var(--muted)}
@media (max-width:560px){.hx-vs,.hx-steps{grid-template-columns:1fr}.hx-stats{gap:6px}.hx-mid{justify-self:center}.hx-vs{text-align:center}}
[data-seq]>*{opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s}[data-seq]>.on{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-seq]>*{opacity:1;transform:none;transition:none}}

/* hero: ticket (2026-10-27) */
.hx-neon{text-align:center}.hx-neon .hx-lead{margin-left:auto;margin-right:auto}
.hx-neon .hx-h1 em{color:#ff4fc4;text-shadow:0 0 18px #ff4fc4aa}
.hx-ticket{display:flex;max-width:680px;margin:0 auto;text-align:left;background:#1d1436;border:1.5px solid #ff4fc4;border-radius:16px;box-shadow:0 0 24px #ff4fc444;overflow:hidden}
.hx-tk-main{flex:1;padding:16px 20px}.hx-tk-h{font-weight:800;font-size:17px;margin-bottom:6px}.hx-tk-h small{font-size:12px;color:#b9b0d6;margin-left:8px;font-weight:500}
.hx-check{list-style:none;margin:0;padding:0;columns:2;column-gap:18px;font-size:14px}
.hx-check li{padding:3px 0 3px 26px;position:relative;break-inside:avoid}
.hx-check li::before{content:"";position:absolute;left:0;top:7px;width:16px;height:16px;border:2px solid #9f7bff;border-radius:4px}
.hx-check li.on::after{content:"✓";position:absolute;left:3px;top:0;color:#ff4fc4;font-weight:800;text-shadow:0 0 8px #ff4fc4}
.hx-tk-stub{flex:0 0 150px;border-left:2px dashed #9f7bff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;padding:14px;background:#271c47;position:relative}
.hx-tk-stub::before,.hx-tk-stub::after{content:"";position:absolute;left:-11px;width:20px;height:20px;border-radius:50%;background:var(--bg)}.hx-tk-stub::before{top:-10px}.hx-tk-stub::after{bottom:-10px}
.hx-tk-stub span{font-size:12px;color:#b9b0d6}.hx-tk-stub b{font-size:22px;color:#ff4fc4;text-shadow:0 0 12px #ff4fc4}
.hx-go{display:inline-block;margin-top:6px;background:#ff4fc4;color:#1a0b2e;text-decoration:none;font-weight:800;font-size:13px;padding:7px 14px;border-radius:99px;box-shadow:0 0 14px #ff4fc488}
.hx-neon .hx-chips{justify-content:center}.hx-neon .hx-chips a{color:#e6dcff;border:1.5px solid #9f7bff88;border-radius:99px}.hx-neon .hx-chips a:hover{border-color:#ff4fc4;color:#ff4fc4}
.hx-neon .hx-vs{background:linear-gradient(90deg,#1d1436,#2b1652);border:1px solid #3a2d63;border-radius:18px;padding:20px 14px}
.hx-neon .hx-side.on .hx-v{color:#ff4fc4;text-shadow:0 0 14px #ff4fc488}.hx-neon .hx-mid{color:#9f7bff;font-weight:800}
.hx-neon .hx-stats div{border:1px solid #3a2d63;border-radius:14px;padding:14px 6px;background:#1d1436}
.hx-neon .hx-stats b{font-size:clamp(30px,5vw,44px);color:#fff;text-shadow:0 0 10px #9f7bff,0 0 22px #ff4fc4}
.hx-neon .hx-steps{text-align:left}.hx-neon .hx-steps li{background:#1d1436;border-radius:12px;padding:12px 14px;border-left:4px solid #ff4fc4}
.hx-neon .hx-steps b{font-size:12px;color:#ff4fc4;letter-spacing:.1em}
@media (max-width:560px){.hx-ticket{flex-direction:column}.hx-tk-stub{flex:auto;border-left:0;border-top:2px dashed #9f7bff}.hx-tk-stub::before,.hx-tk-stub::after{display:none}.hx-check{columns:1}}
